export function glossaryForWeek(entries, session) {
 return weeklyGlossaryTerms[session.number].map(word=>{
  const entry=entries.find(g=>g.word===word);
  if(!entry||!glossaryDefinitions[word])throw new Error('Falta el término semanal: '+word);
  return {...entry,definition:glossaryDefinitions[word].replace(/((?:[^.!?]+[.!?] ){2})/,first=>first.trim()+'\n\n'),reference:session.passage,week:session.number};
 });
}
export function insightFor(word,verses,definition){
 const ranges=[['2Sam.7',8,16],['Isa.9',1,7],['Mic.5',1,5],['Isa.49',1,6],['Luke.1',5,25],['Luke.1',26,38],['Luke.1',39,56],['Luke.2',1,7],['Luke.2',8,20],['Luke.2',21,38],['Luke.2',39,52],['Luke.3',1,22]];
 const index=ranges.findIndex(([chapter,start,end])=>verses.length&&verses.every(v=>v.key?.split('.').slice(0,2).join('.')===chapter&&v.verse>=start&&v.verse<=end));
 const note=weeklyWordNotes[index+1]?.[word];
 if(note){const meaning=definition?.match(/^[\s\S]*?[.!?](?:\s|$)/)?.[0]?.trim();return meaning?meaning+'\n\n'+note:note;}
 return glossaryDefinitions[word]||definition;
}
